// TH14 synthetic training aliases used by this card; see transcribe/th14/bullet-types.md.
// Native type -> target slot: 0..23 same number, 24..42 target +1. Radii/colors pre-verified.
const TH14_BALL2: int = 432;      // native type 5
const TH14_ARROWHEAD: int = 544;  // native type 12

// TH14 v1.00b st01bs::Boss1 nonspell. Entry source49-87; helpers Boss1_at:89-121, Boss1_at2:123-164.
// Shell: pattern starts at card frame ~120; source t0 is its first frame (source timerReset:53).
// Source window [0,2100) = original interrupt timer; 360-frame bullet tail included in TIME_LIMIT.
const TIME_LIMIT: int = 2584;
const SOURCE_LIMIT: int = 2100;
const OPENING_BUFFER: int = 120;

// Source Boss1_at(A=$D, B=%E). etAim(0,1) is a fixed-direction fan; every volley overwrites the
// initial etAngle with etAngle(0,%C,0.7853982) so the live spacing is 45deg (0.0327 is dead).
async sub boss1_at(n: int, dir: angle) {
    // Source reads %ANGLE_PLAYER once at helper entry; %C = ANGLE_PLAYER - B*5.
    var until: int = self_int(1);
    var rank: int = global(GVAR_RANK);
    var spd: fx = 1.4fx;
    if rank == 2 { spd = 1.9fx; }
    if rank == 3 { spd = 2.8fx; }
    var aim: angle = aim_player();
    var a: angle = aim-(((dir as int)*5) as angle);
    sh_reset(0);
    sh_aim(0, 0);                    // source etAim(0,1)
    sh_ring(0, 0);                   // fan
    sh_sprite(0, TH14_ARROWHEAD, 6); // source etSprite(0,12,6)
    sh_count(0, n, 1);               // source etCount(0,$A,1); $A is the caller's $D
    sh_speed(0, spd, 0fx);           // source etSpeed(0,[rank],1.0f), single layer
    // Source etDist20 plus birth ANIM retreat -4*initial speed (a=1 path); birth anim otherwise omitted.
    sh_dist(0, 20fx-4fx*spd);
    for i in 0..12 {
        if $frame >= until { return; }
        sh_angle(0, a, 45deg);       // source etAngle(0,%C,0.7853982)
        a = a+dir;                   // %C = %C + %B
        sh_fire(0);                  // source etOn(0)
        wait(4);                     // source wait(4); 12 volleys then return
    }
}

// Source Boss1_at2(A=$D): A is never read inside the helper.
async sub boss1_at2(n: int) {
    wait(120);                       // source wait(120) before configuring emitter 1
    var until: int = self_int(1);
    var rank: int = global(GVAR_RANK);
    var spd: fx = 0.8fx;
    if rank == 2 { spd = 1.8fx; }
    if rank == 3 { spd = 2.8fx; }
    var interval: int = 40;
    if rank == 1 { interval = 16; }
    if rank == 2 { interval = 10; }
    if rank == 3 { interval = 3; }
    sh_reset(1);
    sh_aim(1, 0);                    // source etAim(1,1)
    sh_ring(1, 0);
    sh_sprite(1, TH14_BALL2, 6);     // source etSprite(1,5,6)
    sh_count(1, 1, 1);               // source etCount(1,1,1)
    sh_speed(1, spd, 0fx);           // source etSpeed(1,[rank],1.0f)
    // No etDist in source; birth ANIM retreat -4*initial speed remains.
    sh_dist(1, 0fx-4fx*spd);
    // Source loops 6000 times; every interval >=3, so the source interrupt bounds it long before.
    loop {
        if $frame >= until { return; }
        // Source etOffsetRad(1,%RANDRAD,%RANDF*32): angle draw first, radius draw second.
        var ra: int = rand(65536)-32768;
        var u: fx = (rand(65536)-32768) as fx / 65536 + 0.5fx;
        sh_offset_rad(1, ra as angle, u*32fx);
        // Source %B = ANGLE_PLAYER + RANDRAD/4; etAngle(1,%B,0); etOn(1).
        sh_angle(1, aim_player()+((ra/4) as angle), 0deg);
        sh_fire(1);
        wait(interval);
    }
}

async sub pattern() {
    wait(OPENING_BUFFER);
    var until: int = $frame+SOURCE_LIMIT; // source timerReset:53, interrupt timer 2100
    set_self_int(1, until);
    set_self_int(0, 30);                  // velocity 0 until the first source moveRand
    set_self_fx(0, 0fx);
    set_self_fx(1, 0fx);
    var rank: int = global(GVAR_RANK);
    // Source diffI($D,2,2,4,6) -> Boss1_at count. Outer diffI($A,90,90,40,40) is not read here.
    var n: int = 2;
    if rank == 2 { n = 4; }
    if rank == 3 { n = 6; }
    // Source outer wait mask: E/N 120, H 80, L 55.
    var gap: int = 120;
    if rank == 2 { gap = 80; }
    if rank == 3 { gap = 55; }
    var dir: angle = 3641 as angle;       // source %E = 0.349066 rad (20deg)
    card_wait_until(60, until);           // source wait(60) after timerReset
    if $frame < until {
        spawn boss1_at2(n);               // source @Boss1_at2($D) async (D unread)
        while $frame < until {
            card_wait_until(20, until);   // Boss1_472: wait(20)
            if $frame >= until { break; }
            spawn boss1_at(n, dir);       // source @Boss1_at($D,%E) async
            dir = -dir;                   // %E = %E * -1
            card_wait_until(gap, until);  // source rank wait
            if $frame >= until { break; }
            card_move_rand();             // source moveRand(30,4,2.0f)
            card_wait_until(32, until);   // source wait(32)
        }
    }
    move_vel(0, 0deg, 0fx, EASE_LINEAR);  // native interrupt/next-card stops old velocity
}

async sub boss_main() {
    set_invuln(65535);
    set_hitbox(24fx);  // source setHitbox(48,48): ordinary circle radius = width*0.5
    set_hurtbox(20fx); // source setHurtbox(40,40)
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    move_vel(0, 0deg, 0fx, EASE_LINEAR);
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 128fx, 11300, 0, 0, 0, boss_main);
    loop { wait(600); }
}

// TH14 v1.00b st01bs::Boss1 moveRand(30,4,2.0f) under moveLimit(0,128,280,64).
// Same verified modern-series moveRand recipe as TH18/TH16 (transcribe/th16/movement.md):
// direction sampled once at the call from FINAL position and player x; speed(k)=v0*(1-k/N);
// target position clamped per tick to x[-140,140] y[96,160] (limit center 0,128, full 280x64).
// Owner slots: int0=next-step index, int1=source end frame (set by pattern), fx0/1=unit vector.
// The card pattern task is the only movement driver; child emission tasks never arm steps.

sub card_arm_next_step() {
    var k: int = self_int(0)+1;
    set_self_int(0, k);
    var speed: fx = 0fx;
    if k < 30 { speed = 2fx*((30-k) as fx)/30fx; }
    var nx: fx = $self_x+self_fx(0)*speed;
    var ny: fx = $self_y+self_fx(1)*speed;
    if nx < -140fx { nx = -140fx; }
    if nx > 140fx { nx = 140fx; }
    if ny < 96fx { ny = 96fx; }
    if ny > 160fx { ny = 160fx; }
    move_vel_xy(0, nx-$self_x, ny-$self_y, EASE_LINEAR);
}

sub card_begin_angle(a: angle) {
    set_self_fx(0, cos(a));
    set_self_fx(1, sin(a));
    set_self_int(0, 0);
    card_arm_next_step();
}

sub card_move_rand() {
    // Signed unit random * pi; values below are unwrapped BAM ints.
    var r: int = rand(65536)-32768;
    var a: int = r/3;
    // Inner direction region = limit center +- width/4 = x +-70, y 112..144.
    if $self_x < -70fx {
        a = r/3;
    } else if $self_x > 70fx {
        a = r/3+32768;
        if a > 32768 { a = a-65536; } // source explicitly normalizes this branch
    } else {
        a = r/4;
        var choose: int = rand(65536)%3; // source WORD modulo3, including its tiny bias
        if $player_x > $self_x {
            if choose == 0 { a = a+32768; }
        } else {
            if choose != 0 { a = a+32768; }
        }
        // Deliberately not normalized before the source fabs tests.
    }
    if $self_y < 112fx {
        if a < 0 { a = -a; }
    } else if $self_y > 144fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    // Native +-pi/2 guard, epsilon 0.05rad; nearest BAM boundaries.
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    card_begin_angle(a as angle);
}

sub card_wait_until(frames: int, until: int) {
    // Same per-frame movement arming as the verified card_wait, but stops at the source cutoff.
    for i in 0..frames {
        if $frame >= until { return; }
        wait(1);
        card_arm_next_step();
    }
}
